n/vnd.kubernetes.protobuf\":{\"schema\":{\"\$ref\":\"https://openapi.invalid/schema/root-13a44ba510a55bd4406e.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.WatchEvent\"}},\"application/vnd.kubernetes.protobuf;stream=watch\":{\"schema\":{\"\$ref\":\"https://openapi.invalid/schema/root-13a44ba510a55bd4406e.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.WatchEvent\"}},\"application/yaml\":{\"schema\":{\"\$ref\":\"https://openapi.invalid/schema/root-13a44ba510a55bd4406e.json#/components/schemas/io.k8s.apimachinery.pkg.apis.meta.v1.WatchEvent\"}}},\"description\":\"OK\"},\"401\":{\"description\":\"Unauthorized\"}},\"tags\":[\"autoscaling_v2\"],\"x-kubernetes-action\":\"watchlist\",\"x-kubernetes-group-version-kind\":{\"group\":\"autoscaling\",\"kind\":\"HorizontalPodAutoscaler\",\"version\":\"v2\"}},\"parameters\":[{\"description\":\"allowWatchBookmarks requests watch events with type \\\"BOOKMARK\\\". Servers that do not implement bookmarks may ignore this flag and bookmarks are sent at the server's discretion. Clients should not assume bookmarks are returned at any specific interval, nor may they assume the server will send any BOOKMARK event during a session. If this is not a watch, this field is ignored.\",\"in\":\"query\",\"name\":\"allowWatchBookmarks\",\"schema\":{\"type\":\"boolean\",\"uniqueItems\":true}},{\"description\":\"The continue option should be set when retrieving more results from the server. Since this value is server defined, clients may only use the continue value from a previous query result with identical query parameters (except for the value of continue) and the server may reject a continue value it does not recognize. If the specified continue value is no longer valid whether due to expiration (generally five to fifteen minutes) or a configuration change on the server, the server will respond with a 410 ResourceExpired error together with a continue token. If the client needs a consistent list, it must restart the